(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["to"] = {"ui":{"skip":"Ō ki he meʻa ʻoku ʻi loto","back":"← Foki ki he AI-gile","lang.button":"Lea: {name}","lang.dialog":"Fili ha lea","lang.search":"Kumi lea","lang.none":"ʻIkai ha lea ʻoku fehoanaki","lang.notYet":"Kuo teʻeki liliu ʻa e {name}","theme.aria":"Fetongi ʻi he tema maama mo e tema fakapoʻuli","theme.toLight":"Fetongi ki he tema maama","theme.toDark":"Fetongi ki he tema fakapoʻuli","words.underline":"Tohi ha laine ʻi lalo ʻo e ngaahi foʻi lea ni ʻi he peesí","words.underlineHelp":"Tuku ʻa e māusi ʻi ha foʻi lea ʻoku ʻi ai hono ngaahi poini pe tā ia ke sio ki hono ʻuhingá.","index.title":"AI-gile: hoʻo kautaha AI faʻu polokalama, ʻi he laupapa pe taha","index.description":"Ko e AI-gile ko ha laupapa kanban ia maʻa e ngaahi kautaha AI ʻoku nau tohi kouti. ʻOku nau ngāue lolotonga hoʻo mohe; te ke maʻu ha fanga kiʻi haʻanga nounou ʻo e ngaahi meʻa ke ke fili, sivi mo tali.","hero.logoAlt":"Ikoni ʻo e laupapa AI-gile","hero.h1.html":"Hoʻo kautaha AI faʻu polokalama, ʻi he laupapa pe&nbsp;taha.","hero.alpha":"🐣 Pre-alpha tāpuni","hero.alphaTitle":"ʻOku teʻeki ke kakato: mālō hoʻo feinga!","hero.lede":"ʻOku nau faʻu lolotonga hoʻo mohe. ʻE ke ʻā ʻo maʻu ha haʻanga nounou pe taha: ngaahi fehuʻi siʻi, ngaahi meʻa siʻi ke sivi, mo ha taimane violeti ʻe taha pe ua. Lomiʻi, tali, pea foki ki hoʻo kofi.","dl.windows":"Polokalama Windows","dl.browser":"Fakaʻaonga ʻi he polokalama kumi","dl.soon":"ʻOku haʻu ʻi he vave","dl.notify":"🔔 Fakamatala mai ʻo ka ava","dl.notifySmall":"Alpha pe beta","hero.secondary":"Agile, ka ʻoku ʻikai fiemaʻu ʻe he kautaha ha kofi stand-up. (ʻOku nau fai pē stand-up.)","pitch.h2":"AI-gile ʻi he ngaahi lea ʻe lahi ʻaki hoʻo loto","pitch.lede":"Fili ha lōloa, mei he lea pe taha ki he 144. ʻOku taki taha ʻa e lōloa ko ha fakamatala makehe, naʻe tohi maʻa e lahi ko iá. Toho e slider pe ngāueʻaki e ngaahi ki ʻaro (arrow keys).","pitch.rangeLabel":"Lōloa ʻi he ngaahi lea","pitch.dice":"🎲 toe ʻuhinga kehe","pitch.words.one":"lea ʻe {n}","pitch.words.other":"lea ʻe {n}","pitch.letters.one":"mataʻitohi ʻe {n}","pitch.letters.other":"mataʻitohi ʻe {n}","pitch.chars.one":"fakaʻilonga ʻe {n}","pitch.chars.other":"fakaʻilonga ʻe {n}","count.line.html.one":"kaati ʻe {n} ʻi he laupapa he taimi ni","count.line.html.other":"kaati ʻe {n} ʻi he laupapa he taimi ni","features.aria":"ʻOku ne faí","f.pile.h":"Haʻanga pe taha maʻau","f.pile.html":"Ko e <b>Maʻau</b> ʻoku ne tauhi ʻa e meʻa kotoa ʻoku tatali kiate koe, ʻi he poloseki kotoa: ngaahi fehuʻi, ngaahi meʻa ke sivi, ngaahi ngāue ʻoku faʻa fai pē ʻe he tangata. ʻOku fakahā ʻe hoʻo laine ʻa e meʻa hokó mo e taimi ʻe fie maʻu.","f.sleep.h":"Ngaahi kautaha ʻoku ngāue lolotonga hoʻo mohe","f.sleep.p":"Ko e poloseki kotoa pē ʻoku ʻi ai ha taki mo ha kautaha ʻo e ngaahi ʻeiseniti AI. Fakahā ha fakakaukau ʻi ha kaati pea ʻe ʻā ʻa e kautaha, fai e ngāue, pea ʻoatu ia mo e ngaahi sitepu ʻe lava ke muimui ai ha tangata ongosia.","f.tester.h":"ʻOku sivi ʻuluaki ʻe he sivi AI","f.tester.p":"Ki muʻa ke aʻu ha meʻa kiate koe, ʻoku muimui ʻa e sivi ʻi he ngaahi sitepu ʻi ha kopi ʻo e polokalama pea fakahā ʻa e meʻa naʻá ne sio ki ai, mo ha screenshot. Lau fakavave ʻa e ngaahi meʻa kuo pasi pea tali ʻaki ha lomiʻi pe taha.","f.proof.h":"Fakamoʻoni, ʻikai ko e ngaahi talaʻofa","f.proof.p":"Ko e tuku atu kotoa ʻoku fakahā ai ʻa e meʻa kuo liliu: ngaahi faile, kehekehe, mo e ngaahi screenshot. ʻIkai fiemaʻu ke fakaava ʻa e polokalama kotoa ke sio pe kuo kakato.","f.chat.h":"Talanoa mo hoʻo ngaahi taki","f.chat.p":"Ko ha kolomu hangē ko e Discord: ko e fakaʻilonga pe taha ki he poloseki taki taha, taimane violeti maʻa e meʻa ʻoku fiemaʻu ai koe. Fekau ha fakakaukau ki ha taki; te ne liliu ia ki he ngaahi kaati mo ha palani, mo ha pātani ✅ Ō.","f.tidy.h":"ʻOku tauhi ʻe ia ʻa ia ke lelei","f.tidy.p":"Ko e ngaahi kaati fekauʻaki ʻoku fakataha ʻo hoko ko e taha, ko e ngaahi ʻulu hala ʻoku fakatonutonu, pea ʻoku tauhi ʻe he sivi tokeni ʻa e kouti ke maʻama. Siʻi ange ʻa e ngaahi meʻa ke fetongi, siʻi ange ʻa e fakakaukau.","f.private.h":"Ko hoʻo meʻa, ʻi hoʻo komipiuta","f.private.li1":"ʻOku ngāue ʻa e laupapa ʻi hoʻo komipiuta pea tali pē kiate koe.","f.private.li2":"Ko e ngaahi pōpoaki fakapulipuli ʻo e kakai ʻoku fakapulipuliʻi mei he ʻuluaki ki he ngataʻanga (end-to-end).","f.private.li3":"ʻIkai ha akaunití, ʻikai ha toʻo fakaʻilonga, ʻikai ha kuki.","f.lang.h":"ʻI hoʻo lea","f.lang.p":"Lea ʻe laka hake he 120, mei he lea faka-Hōlani, faka-Uēlesi mo faka-Siapani ki he kaniva, Yoda mo e Klingon, mo ha fetongi vave ki he lea fakapālangi maʻa e ngaahi lea faʻu polokalama.","tl.aria":"Laine ʻo e taimi mei he talanoa ʻuluaki ki he palani","tl.h2":"Mei he talanoa ʻuluaki ki he meʻa hoko mai","tl.lede":"Ngaahi ʻaho mo e taimi moʻoni, ʻi hoʻo feituʻu taimi. Hili e ʻahó ni ko e palani pē ia, ʻikai ha ʻaho kuo talaʻofa.","tl.today":"ʻAhó ni","tl.planned":"kuo palani","tl.cards.one":"kaati ʻe {n}","tl.cards.other":"kaati ʻe {n}","join.h2":"Kau mai","join.lede":"ʻOku faʻu ʻa e AI-gile ʻe ha tangata siʻi mo ha ngaahi ʻeiseniti kātaki lahi. ʻOku fakapulipuli he taimi ni, ʻi ha alpha tāpuni mo e ngaahi kaungāmeʻa. Te ke loto ke ke feinga ʻo ka ava?","join.btn":"Hiki hoʻo fie maʻu","join.small":"Te mau imeili atu, ʻikai ha toe meʻa","footer.tag":"AI-gile. ʻIkai ha toʻo fakaʻilonga, ʻikai ha kuki, ʻikai ha kofi stand-up.","footer.licence":"Laiseni pisinisi","footer.status":"Tuʻunga","footer.privacy":"Meʻa ʻoku mau tauhi","form.sending":"ʻOku fekau…","form.failed":"Naʻe ʻikai lava: feinga ʻo toe hili ha taimi.","form.offline":"Naʻe ʻikai lava ke aʻu ki he AI-gile: feinga ʻo toe hili ha taimi.","form.keep":"ʻOku mau fakaʻaongaʻi pē ia ke tali atu kiate koe, pea mau toki tamateʻi. ʻIkai ha toʻo fakaʻilonga, ʻikai ha kuki.","form.keepLink":"Meʻa ʻoku mau tauhi","interest.title":"AI-gile: fakamatala mai ʻo ka ava ʻa e alpha","interest.description":"Tuku mai hoʻo imeili ke ke ʻilo ʻo ka ava ʻa e alpha tāpuni pe beta ʻa e AI-gile.","interest.h1":"🔔 Fakamatala mai ʻo ka ava","interest.lede":"ʻOku ʻi he pre-alpha tāpuni ʻa e AI-gile. Tuku mai hoʻo imeili pea te mau tohi atu taha pē, ʻo ka ʻi ai ha potu maʻau.","interest.email":"Hoʻo imeili","interest.which":"Sivi fē?","interest.alpha":"Alpha tāpuni: kei ʻuluaki, matolu, liliu lahi","interest.beta":"Beta: lelei ange, hili ʻeni","interest.both":"ʻIkai ha meʻa, ko ia ʻe hoko ʻuluaki","interest.submit":"Fakahū au ki he lisi","interest.thanks":"Mālō! ʻOku ʻi he lisi koe.","licence.title":"AI-gile: laiseni pisinisi","licence.description":"ʻOkú ke fakaʻaongaʻi ʻa e AI-gile ʻi hoʻo pisinisi? Kole ha laiseni pisinisi ʻikai ha totongi.","licence.h1":"📜 Laiseni pisinisi","licence.lede":"ʻOkú ke fakaʻaongaʻi ʻa e AI-gile ʻi he ngāue? Tala mai pe ko hai koe mo e meʻa ʻokú ke faí. Kapau ʻoku fai ha lelei, ʻikai ha totongi ʻa e laiseni.","licence.company":"Kautaha","licence.website":"Uepisaiti","licence.what":"Meʻa ʻokú ke faí","licence.how":"Founga ʻoku tokoni ai ki he māmani","licence.email":"Imeili","licence.submit":"Kole","licence.thanks":"Mālō! Te mau tali ʻaki e imeili.","status.title":"Tuʻunga ʻo e AI-gile","status.h1":"Tuʻunga ʻo e AI-gile","status.quiet":"Tuʻu fiemālie","status.intro":"ʻOku ngāue ʻa e AI-gile he taimí ni? ʻOku sivi ʻe he peesi ni ʻa e uepisaiti, vahevahe laupapa, telefoni mo e download ʻi he miniti ʻe 5 kotoa pē.","status.up":"ʻOku ngāue (naʻe tali ʻi he {ms} ms)","status.slow":"Naʻe ʻikai tali ʻi he sivi fakamuimuí, ʻoku toe feinga","status.down":"Mate: naʻe ʻikai tali ʻi he sivi fakamuimui ʻe uá","status.svc.web":"Uepisaiti","status.svc.web.offers":"Ko e saiti ni: ko e hā ʻa e AI-gile, mo e foomu fie maʻu","status.svc.boards":"Vahevahe laupapa","status.svc.boards.offers":"Ngaahi laupapa maʻa e kakai kotoa, ngaahi pōpoaki ʻi he vahaʻa ʻo e ngaahi kaungāmeʻa mo e ngaahi fakaafe","status.svc.calls":"Telefoni","status.svc.calls.offers":"Leʻo, vitiō mo e vahevahe sikilini ʻi he AI-gile","status.svc.download":"Download","status.svc.download.offers":"Ko e polokalama fokotuʻu ki he Windows mo e ngaahi link fakaafe","status.checking":"ʻOku sivi…","status.offline":"ʻOku ʻikai lava ke aʻu ki he tokoni tuʻunga he taimi ni (ʻoku toe feinga)","status.updated":"kuo fakafoʻou {ago}","status.justNow":"he taimi pē ni","status.min":"miniti ʻe {n} kuo hili","status.hours":"houa ʻe {n} kuo hili","status.days":"ʻaho ʻe {n} kuo hili","privacy.title":"AI-gile: meʻa ʻoku mau tauhi","privacy.h1":"Meʻa ʻoku mau tauhi","privacy.lede":"Fakanounou: ko e meʻa pē ʻokú ke fekau mai, pea ʻikai fuoloa.","privacy.only":"Ko e meʻa pē ʻokú ke fekau mai: ko e meʻa ʻokú ke tohi ʻi ha foomu, hangē ko hoʻo imeilí. ʻIkai ha toe meʻa kehe fekauʻaki mo koe.","privacy.sealed":"ʻOku silaʻi ia koeʻuhi ke ʻoua naʻa lava ʻe homau sēvá ʻo lau: ʻi hoʻo browser kimuʻa pea ʻalu (ʻi ha browser motuʻa, ʻi he taimi pē ʻoku aʻu mai ai). Ko homau laupapá pē ʻe lava ʻo fakaava ia.","privacy.server":"ʻOku tamateʻi ia mei he sēvá ʻi he taimi pē ʻoku aʻu ai ki homau laupapá. Ko ha meʻa ʻoku kei ʻi ai hili ha ʻaho ʻe 30 ʻoku tamateʻi pē ia.","privacy.board":"ʻOku mau tauhi ia ʻi homau laupapá kae ʻoua kuo mau tali atu kiate koe, pea mau toki tamateʻi foki ia ʻi ai.","privacy.none":"ʻIkai ha toʻo fakaʻilonga, ʻikai ha kuki, ʻikai ha fakatotolo fakafika.","privacy.local":"Ko hoʻo leá mo hoʻo fili ʻo e maama pe fakapoʻulí ʻoku nofo pē ʻi hoʻo browser. ʻOku ʻikai teitei fekau mai ia kiate kimautolu.","privacy.ask":"Fie tamateʻi vave ange? Tali mai ki heʻemau imeilí ʻo tala mai.","live.h2":"Sio ki he'ene langa, mo'ui","live.caption":"Kuo fufū e kaati kotoa: ke ke sio ki he tafa'aki 'o e ngāue, 'ikai ko e ngaahi lea.","live.watching.one":"mo'ui: {n} 'oku sio","live.watching.other":"mo'ui: {n} 'oku sio","live.last.now":"Naʻe ʻosi pē hono ʻave ʻa e kaati fakaʻosi","live.last.min.one":"Naʻe ʻave ʻa e kaati fakaʻosi miniti ʻe {n} kuo hili","live.last.min.other":"Naʻe ʻave ʻa e kaati fakaʻosi miniti ʻe {n} kuo hili","live.last.hour.one":"Naʻe ʻave ʻa e kaati fakaʻosi houa ʻe {n} kuo hili","live.last.hour.other":"Naʻe ʻave ʻa e kaati fakaʻosi houa ʻe {n} kuo hili","live.last.day.one":"Naʻe ʻave ʻa e kaati fakaʻosi ʻaho ʻe {n} kuo hili","live.last.day.other":"Naʻe ʻave ʻa e kaati fakaʻosi ʻaho ʻe {n} kuo hili","live.offline":"'Oku mālōlō si'i e palaoti mo'ui. Foki mai 'i he vave.","live.cols":"Backlog|Ke fai|ʻOku fakahoko|Sivi ʻe he kautaha|Maʻau ke test|Maʻá e kautaha|Kuo fai"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Lopoti.","Tuku."]},{"n":2,"texts":["Kanban lopoti.","ʻEiseniti faʻu.","Fakakaukau, faʻu."]},{"n":3,"texts":["Kanban maʻa lopoti.","Fakakaukau hoko moʻoni.","Kanban ʻeiseniti taʻetotongi."]},{"n":5,"texts":["Laupapa kanban ʻoku ngāue ʻeiseniti.","Tohi kaati. ʻEiseniti te nau faʻu.","Taʻetotongi, ʻi he komipiuta, kuo sivi."]},{"n":8,"texts":["Laupapa kanban taʻetotongi ʻoku ngāue ai ʻeiseniti AI.","Tohi ha fakakaukau. ʻEiseniti te nau faʻu. Te ke tali.","Agile maʻa ha tangata mo e lopoti kātaki."]},{"n":13,"texts":["Laupapa kanban ʻi hoʻo komipiuta ʻoku toʻo ai ʻe he ʻeiseniti AI ʻa e kaati.","Tohi ha fakakaukau. Te nau faʻu ia, pea te ne siviʻi ʻe ha sivi.","Taʻetotongi, ʻikai ha akaunití: ko ha laupapa, ngaahi lopoti, pea ko koe ʻoku takí."]},{"n":21,"texts":["Ko e AI-gile ko ha laupapa kanban ia ki he ngāue mo e ʻeiseniti AI. ʻOku nau toʻo e kaati; te ke sivi mo tali.","Ko e poloseki kotoa ʻoku ʻi ai ha taki mo ha kautaha ʻeiseniti AI. Fakahā ʻi ha kaati pea ʻoku ngāue ʻa e kautaha.","Ko ha laupapa fakafoʻituitui taʻetotongi ʻoku ngāue ʻi hoʻo komipiuta. Ko e kau ngāue ko e lopoti. Ko koe ʻoku pehē ʻio."]},{"n":34,"texts":["Tuku e fakakaukau ki ha laupapa. Ko e kautaha ʻeiseniti AI ʻoku liliu ia ki he meʻa ʻoku ngāue, sivi ia, pea foki mai mo e sitepu. ʻIkai ha meʻa kuo fai kae ʻoua ke ke pehē.","Ko e AI-gile ko ha laupapa kanban naʻe faʻu ʻe Rich mo e tokoni lahi mei he ngaahi ʻeiseniti. ʻOku taʻetotongi, ngāue ʻi hoʻo komipiuta, pea vahevahe mo e kaungāmeʻa, ʻikai fakatau atu.","Fakakaukauʻi ha laupapa kanban angamaheni, mei he Backlog ki he Kuo fai, ka ko e ʻeiseniti AI ʻoku toʻo e kaati. ʻOku nau fakahā e fakalakalaka, fehuʻi ʻo ka tuʻu, pea tatali ki hoʻo tali."]},{"n":55,"texts":["Ko e AI-gile ko ha laupapa kanban ʻa ia ko e kautaha ko e ʻeiseniti AI. Ko e poloseki kotoa ʻoku ʻi ai ha taki ʻoku palani mo ha kau tokoni ʻoku faʻu. ʻO ka mateuteu, ʻoku sivi ʻe ha sivi AI pea tā ha screenshot, pea hoko ia ki hoʻo haʻanga. Tali ia, pe fakahā pea nau toe fai.","Naʻe kamata ia ko e founga ʻa ha tokotaha ke muimui ki he ngaahi seti AI lahi taha, pea tupu ko ha laupapa totonu. ʻOku ngāue ʻi hoʻo komipiuta, ʻikai fiemaʻu ha akaunití, ʻikai ha toʻo fakaʻilonga. ʻOku taʻetotongi maʻa e kaungāmeʻa. ʻOku kei teʻeki kakato, ko ia ʻamanaki ki ha fakaofo.","ʻOku ʻeni ʻa e tala moʻoni. Kei fiemaʻu ke ke ʻai e ngaahi fakakaukau, pea sivi e ola. Ko e AI-gile ʻoku ne fai e meʻa kotoa ʻi he vahaʻa: tauhi e kaati, ʻā ʻa e ʻeiseniti totonu, fakahā e meʻa kuo liliu, pea tānaki ia ki ha haʻanga nounou maʻau."]},{"n":89,"texts":["Ko e AI-gile ko ha laupapa kanban taʻetotongi ʻokú ke fakahoko ʻi hoʻo komipiuta. ʻI he feituʻu ʻo e kakai, ko e poloseki kotoa ʻoku ʻi ai ha kautaha ʻeiseniti AI: ha taki ʻoku liliu hoʻo fakakaukau ki he kaati mo ha palani, mo e kau tokoni ʻoku toʻo e kaati. ʻO ka faʻu ha meʻa, ʻoku muimui ha sivi AI ki he sitepu pea fakahā kiate koe. Pea tatali ia ʻi ha haʻanga ʻoku ui ko e Maʻau. Tali ia, pe fakahā pea feinga e kautaha ʻo toe. ʻIkai ha meʻa te ne aʻu ki he Kuo fai ʻikai ko koe.","Ko ha ngaahi meʻa ʻe ʻikai te ke ʻamanaki. ʻOku fakafonu ʻe ha leʻo poʻuli ʻa e kolomu Ke fai lolotonga hoʻo mohe, ʻo fili e kaati ʻikai fiemaʻu ha tali meiate koe. ʻOku fakahā ʻe ha tokeni lau ʻa e meʻa kuo ngāueʻaki ʻe he ʻeiseniti, pea tala ʻe he No Token Mode ke tuku e fakamoleki. ʻE lava ke ke fekau pōpoaki ki he kaungāmeʻa, pea ʻoku fakapulipuliʻi mei he ʻuluaki ki he ngataʻanga. ʻOku lea e laupapa ʻi he lea ʻe 120, kau ai e Hōlani, kaniva mo e Klingon. ʻIkai ha totongi, pea ʻikai ha taha ʻoku fakatau atu ha meʻa kiate koe.","Ko e AI-gile ko ha kiʻi poloseki fakafoʻituitui, ʻikai ko ha kautaha. Naʻe fie tauhi ʻe Rich ha ngaahi poloseki AI ʻo ʻikai fakaava e polokalama kotoa, ko ia naʻá ne mo e ʻeiseniti naʻa nau faʻu ha laupapa, pea ngāueʻaki ia ke faʻu e toenga ʻo ia pē. ʻOku ʻi he pre-alpha tāpuni, ʻa ia ʻoku ne ngāue, ʻi he lahi taha, maʻa ha kiʻi kaungāmeʻa. ʻIkai ha pēsi totongi, ʻikai ha nusipepa, ʻikai ha palani tupu. Kapau ʻoku ongo ʻaonga, kole ke feinga ʻo ka toe ava siʻi."]},{"n":144,"texts":["Ko e AI-gile ko ha laupapa kanban maʻa ha tangata pe taha mo e ʻeiseniti AI lahi. ʻOku ngāue ʻi hoʻo komipiuta pea taʻetotongi kakato. ʻOku ke tānaki ha ngaahi poloseki, pea ko e poloseki taki taha ʻoku maʻu ha taki mo ha kiʻi kautaha. ʻOku ke talanoa mo e taki, hangē ko e Discord, pea fakamatala ha fakakaukau; ʻoku liliu ia ʻe he taki ki he kaati mo ha palani, pea tatali kae lomiʻi ʻe koe ʻa e Ō. ʻOku ngāue ʻa e kautaha ʻi he kaati ʻo muimui ki he mahuʻinga, ʻaki ha meʻangāue laine fekau faingofua. Ki muʻa ke foki mai ha meʻa, ʻoku muimui ha sivi AI ki he sitepu ʻi ha kopi ʻo e polokalama pea fakataha ha screenshot. Ko e ngāue kuo kakato ʻoku hoko ki hoʻo haʻanga mo e faile kuo liliu. Tali ia, pe tuku ha fakamatala pea feinga ʻa e kautaha. Ko koe pē te ne lava ʻo hiki ha kaati ki he Kuo fai.","Ko ha ʻaho mo e AI-gile, ʻi he fakafuofua. ʻI he efiafi ʻokú ke tuku ha ngaahi fakamatala siʻi: ko e pātani ni ʻoku hala hono potu, ko e lisi ko ia ke fakahokohoko, ʻe lava nai ha founga fakapoʻuli. ʻOkú ke ʻalu ki he mohe. ʻOku lau ʻe he ʻeiseniti e fakamatala, fai e liliu, sivi ia pea foki mai. Kapau ʻe maha e Ke fai, ʻoku fakafonu ia ʻe he leʻo poʻuli mei he backlog ʻaki e kaati ʻikai fiemaʻu ha tali meiate koe. ʻI he pongipongi ʻoku ʻi ai ha haʻanga nounou pe taha: ha ngaahi fehuʻi siʻi mo ha ngaahi meʻa ke feinga, taki taha mo e sitepu ʻe lava ke muimui ai ha tangata mohe mo ha screenshot. ʻOku ke lomiʻi, tali e lelei pea foki e toenga. ʻOku fakahā ʻe ha tokeni lau e meʻa kuo moleki, pea ʻoku ʻi ai e No Token Mode maʻa e uike fakamālohi. Pea ʻokú ke kai ho pongipongi, ʻa ia ʻoku teʻeki lava ke tokoni ai e ʻeiseniti.","ʻUluaki, ko e meʻa ʻoku ʻikai ko e AI-gile. ʻIkai ko ha kautaha kamata, ʻikai fakatau atu, pea ʻikai ha taha ʻoku tānaki hoʻo fakamatala. Ko ha laupapa taʻetotongi ia ʻoku ngāue ʻi hoʻo komipiuta, ʻikai ha akaunití, ʻikai ha toʻo fakaʻilonga, ʻikai ha kuki. Ko e meʻa ia: ko ha potu pe taha ʻoku maau ke sio ki he poloseki AI kotoa he taimi pē taha, mo ha kautaha ʻeiseniti ʻoku fai e kaati pea ko koe ʻoku fai e fili. ʻOku ne fakataha e kaati fekauʻaki, fakatonutonu e ʻulu hala, pea sio ki he maʻama ʻo e kouti. ʻOku lea ʻi he lea ʻe 120, mei he Hōlani ki he kaniva mo e Klingon. ʻE lava ʻe he kaungāmeʻa ʻo fekau pōpoaki fakapulipuli. Naʻe faʻu ia ʻe Rich mo ha tokolahi ʻo e ʻeiseniti kātaki, ʻaki hono ngāueʻaki ʻa ia pē. ʻOku ʻi he pre-alpha tāpuni, ko ia ʻoku matolu ʻi ha ngaahi potu. Kapau ʻoku fakafiefia, kole fakaʻapaʻapa pea te ke lava ʻo hū vave."]}],"quips":{"1":"Lea pe taha. Toʻa. Mahalo he toʻa tōnunu.","3":"Lea ʻe tolu. Kuo moʻoni ange ia he lahi taha ʻo e peesi ʻo e koloa.","8":"Lea ʻe valu. Kei nounou ange ia he stand-up.","21":"Ko e lōloa ko e story points, ʻo kapau. ʻIo ʻoku pehē.","55":"Lea ʻe nimangofulu-mā-nima. Naʻe kakato ha kaati ʻe ua lolotonga hoʻo lau ʻeni.","144":"Ko e taha lōloa ia. ʻIkai ha 233. Kuo ʻalu e ʻeiseniti ki he mohe."}},"timeline":{"first-idea.name":"Ko e fakakaukau ʻuluaki","first-idea.line":"Ko e talanoa ʻuluaki pē, ki muʻa ke ʻi ai ha kouti.","first-board.name":"Laupapa ʻuluaki","first-board.line":"Ko ha laupapa ʻoku muimui ki hono faʻu ʻo ia: ngaahi kaati, kolomu, toho mo tuku, ngaahi poloseki.","team-roles.name":"Kautaha mo e ngaahi fatongia","team-roles.line":"Ngaahi tohi ʻo e ʻeiseniti, ngaahi sīpinga kautaha, ngaahi potu mo e tokotaha ʻoku fai ʻa e hā.","install.name":"Fokotuʻu mo e ngaahi tuku atu","install.line":"Ko ha zip ʻe lava ke fokotuʻu ʻe ha kaungāmeʻa, fakafoʻou ʻe ia pē, ngaahi hala mo e foki ki mui.","usage-saver.name":"Fakamoleki siʻi","usage-saver.line":"Fua ʻa e totongi ʻo e ngaahi fakahoko, tauhi ʻa e kouti ke maʻama, fakamoleki siʻi hoʻo fakangatangata.","friends.name":"Ngaahi kaungāmeʻa mo e vahevahe","friends.line":"Ngaahi pōpoaki fakapulipuli, relay fakapulipuliʻi, ngaahi fakaafe, ngaahi fatongia mo e ngaahi poloseki vahevahe.","languages.name":"Ngaahi lea","languages.line":"Ko e tohi kotoa ʻo e screen ʻi ha faile lea, mo e lea faka-Hōlani mo e faka-Felemisi ʻuluaki.","ai-tester.name":"Sivi AI","ai-tester.line":"ʻOku sivi ʻuluaki ʻe he sivi ʻa e tuku atu kotoa pea fakahā ʻa e meʻa naʻá ne sio ki ai.","website.name":"Uepisaiti","website.line":"aigile.lol, ko e fanga kiʻi fakamatala mo e laine taimi ni.","streaming.name":"Talanoa mo e streaming","streaming.line":"Discord, Twitch, OBS, founga streamer, ngaahi GIF mo e ngaahi emoji.","no-ai.name":"Tohi ʻikai ha AI","no-ai.line":"Ko ha laupapa maʻa e kakai ʻoku nau tohi kouti ʻikai ha AI, mo e ngaahi laupapa fakamaʻuʻanga.","night-watch.name":"Leʻo poʻuli","night-watch.line":"Ko ha leʻo mo e Scrum Master ʻoku nau tauhi ʻa e ngaahi kautaha ʻi he ngāue lolotonga hoʻo mohe.","p-more.name":"Meʻa kotoa pē kehe","p-more.line":"Ngaahi fakakaukau siʻi ʻoku kei tatali ki honau taimi.","p-android.name":"Telefoni mo e Android","p-android.line":"Aʻu ki hoʻo laupapa mei he telefoni, pea hoko ko e polokalama Android moʻoni.","p-release.name":"Alpha mo e hili ia","p-release.line":"Alpha tāpuni, ko e saiti moʻui, pea beta.","p-languages.name":"Ngaahi lea lahi ange","p-languages.line":"Lea ʻe laka hake he teau, mo ha founga immersion maʻa e kakai ako lea.","p-engines.name":"Ngaahi mīsini AI lahi ange","p-engines.line":"Fili ʻa e Claude, Codex pe Gemini maʻa e ʻeiseniti taki taha.","p-pro.name":"Founga fakapolofesinale","p-pro.line":"Ngaahi fakaʻilonga fakatuʻutāmaki, ngaahi matapā fakataha, ngaahi kaati hoko mo e ngaahi pā fakatauhi.","p-self.name":"Tokangaʻi koe","p-self.line":"Founga ongosia, ngaahi fakamanatu tokangaʻi kita mo e 4:20.","p-servers.name":"Ngaahi sēvā mo e tupu","p-servers.line":"Ngaahi seti ʻo e sēvā fakamāmani, ngaahi fatongia mo e palani ki he tupu.","p-livestream.name":"Ngaahi tānaki streaming","p-livestream.line":"Talanoa Twitch, ngaahi emoji fakafiemālie mo ha sio moʻui maʻa e kakai kotoa."},"words":{"button":"📖 Ngaahi lea polokalama","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Kumi ha lea…","none":"ʻIkai ha lea ʻoku tatau.","close":"Tāpuni","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Ko e folda ʻo e poloseki ʻo e koloa mo hono hisitōlia kakato ʻo e ngaahi commit, ʻoku fa'a tauhi foki ʻi he GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Ko ha laine ngāue kehe ʻi he koloa, ke lava ʻo fai ha ngaahi liliu taʻe ala ki he tuʻunga ʻaupito.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Ko ha tā kuo tauhi ʻo e koloa, mo ha fakamatala nounou ʻo e me'a naʻe liliu. Te ke lava maʻu pē ʻo foki ki ha taha.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Fekau e ngaahi tā kuo tauhi (commits) mei he komipiuta ni ki he GitHub, ke tauhi mo vahevahe."},{"id":"merge","g":"build","word":"Merge","text":"Fakahoko e ngaahi liliu ʻo ha branch ki he tuʻunga ʻaupito."},{"id":"pr","g":"build","word":"Pull request","text":"Kole ke sivi mo fakatahaʻi ʻa e ngaahi liliu ʻo ha branch ki he tuʻunga ʻaupito.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Fakama'a e koloa taʻe liliu e me'a ʻoku ne fai: ngaahi fail siʻi ange, ngaahi hingoa mahino ange, toe lahi ange."},{"id":"bug","g":"build","word":"Bug","text":"Ko ha me'a ʻoku ʻikai ngāue ʻo hangē ko e meʻa ʻoku totonu ke ngāue ai.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Feinga ki ha konga ngāue kuo ʻosi ke sivi pe ʻoku fai ʻa e me'a naʻe kole, kimuʻa pea tali.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Fokotuʻu ha tuʻunga foʻou ke moʻui, hangē ko ha sēvā ʻoku ngāueʻaki ai ʻe he kakai."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ngaahi fakakaukau mo e ngāue te'eki palani. ʻIkai ha me'a ʻe fai ai kae ʻoua ke ʻave ki he Ke fai."},{"id":"sprint","g":"team","word":"Sprint","text":"Ko ha vaha'a ngāue nounou (ʻuhinga ko ha uike pe ua) mo ha ngaahi kaati kuo loto taha ke fakaʻosi.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Ko ha sivi vave: ko e hā naʻe fai ʻe he mēmipa taki taha, ko e hā ʻe fai hoko, pea ko e hā ʻoku taʻofi ai.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Ko ha laupapa mo e ngaahi kolomu (Ke fai, ʻOku fakahoko, Kuo fai) ʻoku ʻalu ai e ngaahi kaati mei he mataʻu ki he maʻu ʻi he taimi ʻoku fai ai e ngāue."},{"id":"wip","g":"team","word":"WIP limit","text":"Ngāue ʻoku fakahoko: ko e lahi taha ʻo e ngaahi kaati ʻe lava ke hao ʻi ha kolomu, ke fakaʻosi ʻe he kautaha e ngaahi me'a kimuʻa pea kamata ha toe.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"Ko ha AI ʻoku ngāue ʻiate ia ki ha ngāue: lau e koloa, fai ha liliu, lele ha ngaahi sivi, pea lipooti mai.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Ko e iuniti ʻoku lau ai e ngāueʻaki AI: ʻuhinga ko ha mataʻitohi siʻi ʻo e tohi kuo lau pe tohi. Token siʻi ange, palani lahi ange ʻoku toe.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Ko ha fekau siʻisiʻi ʻoku lele ʻiate ia ʻi ha taimi kuo fokotuʻu, hangē ko e ʻi he kamata ʻa ha sēsini AI, ke fanongo ʻa e kautaha ki hoʻo ngaahi fakamatala.","also":["hooks"]}]}};
